<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Department;use Illuminate\Http\Request;use Illuminate\Support\Str;class DepartmentController extends Controller{public function index(){return view('admin.catalog.index',['title'=>'Отделения','route'=>'departments','items'=>Department::orderBy('sort')->get()]);}public function create(){return view('admin.catalog.department',['item'=>new Department]);}public function store(Request $r){Department::create($this->data($r));return redirect()->route('admin.departments.index')->with('ok','Отделение создано');}public function edit(Department $department){return view('admin.catalog.department',['item'=>$department]);}public function update(Request $r,Department $department){$department->update($this->data($r));return redirect()->route('admin.departments.index')->with('ok','Сохранено');}public function destroy(Department $department){$department->delete();return back();}private function data(Request $r){$d=$r->validate(['name'=>'required|max:255','description'=>'nullable','sort'=>'nullable|integer']);$d['slug']=Str::slug($r->input('slug')?:$d['name']);$d['is_active']=$r->boolean('is_active');return $d;}}